        "eligible": legitimacy == "LEGIT",
        "verdict": value,
        "legitimacy": legitimacy,
        "selected_relative_path": relative,
        "selected_artifact_sha256": current_hash,
        "selected_verdict_sha256": pipeline_contract.sha256_file(
            execution / "verdict.json"
